=== src/service/RefundBatchJob.java
     1	package service;
     2	
     3	import domain.RefundLine;
     4	import domain.RunResult;
     5	import infra.PgsimClient;
     6	import infra.RefundFileWriter;
     7	import store.RefundRepository;
     8	
     9	import java.nio.file.Path;
    10	import java.time.LocalDate;
    11	import java.time.format.DateTimeFormatter;
    12	import java.util.ArrayList;
    13	import java.util.LinkedHashMap;
    14	import java.util.List;
    15	import java.util.Map;
    16	
    17	/**
    18	 * Nightly refund run: every pending refund line goes to the PG in batches of
    19	 * at most maxLines. Batch id = run id + chunk number; the PG settles and is
    20	 * reconciled per batch id.
    21	 */
    22	public class RefundBatchJob {
    23	    private final RefundRepository refunds;
    24	    private final PgsimClient pg;
    25	    private final String mid;
    26	    private final String prefix;
    27	    private final int maxLines;
    28	    private final Path workDir;
    29	
    30	    public RefundBatchJob(RefundRepository refunds, PgsimClient pg, String mid, String prefix, int maxLines,
    31	                          Path workDir) {
    32	        this.refunds = refunds;
    33	        this.pg = pg;
    34	        this.mid = mid;
    35	        this.prefix = prefix;
    36	        this.maxLines = maxLines;
    37	        this.workDir = workDir;
    38	    }
    39	
    40	    public RunResult run(LocalDate day) {
    41	        String runId = String.format("%s%s-%02d", prefix, day.format(DateTimeFormatter.BASIC_ISO_DATE),
    42	                refunds.nextRunSeq());
    43	        List<RefundLine> pending = uniquePending();
    44	        List<String> batchIds = new ArrayList<>();
    45	        int completed = 0;
    46	        for (int start = 0, chunk = 1; start < pending.size(); start += maxLines, chunk++) {
    47	            List<RefundLine> part = pending.subList(start, Math.min(pending.size(), start + maxLines));
    48	            String batchId = runId + "-" + chunk;
    49	            Path file = RefundFileWriter.write(workDir, batchId, part);
    50	            int accepted = pg.refund(mid, batchId, file);
    51	            if (accepted != part.size()) {
    52	                throw new IllegalStateException("PG accepted " + accepted + " of " + part.size() + " in " + batchId);
    53	            }
    54	            for (RefundLine l : part) l.submitted(batchId);
    55	            batchIds.add(batchId);
    56	            completed += RefundResultMatcher.apply(part, pg.status(batchId));
    57	        }
    58	        int awaiting = (int) pending.stream().filter(l -> l.status() == RefundLine.Status.SUBMITTED).count();
    59	        return new RunResult(runId, List.copyOf(batchIds), pending.size(), completed, awaiting);
    60	    }
    61	
    62	    /** A line queued twice by a CS double-click must be refunded once. */
    63	    private List<RefundLine> uniquePending() {
    64	        Map<String, RefundLine> byKey = new LinkedHashMap<>();
    65	        for (RefundLine l : refunds.pending()) {
    66	            byKey.putIfAbsent(l.orderNo() + "#" + l.lineNo(), l);
    67	        }
    68	        return new ArrayList<>(byKey.values());
    69	    }
    70	}
=== src/infra/RefundFileWriter.java
     1	package infra;
     2	
     3	import domain.RefundLine;
     4	import util.Refs;
     5	
     6	import java.io.IOException;
     7	import java.nio.charset.StandardCharsets;
     8	import java.nio.file.Files;
     9	import java.nio.file.Path;
    10	import java.util.List;
    11	
    12	/** Writes the PG refund batch file: one line per refund, TID TAB AMOUNT TAB merchant reference. */
    13	public final class RefundFileWriter {
    14	    private RefundFileWriter() {}
    15	
    16	    /** Merchant reference printed on the PG settlement file so finance can trace the refund to our order. */
    17	    public static String merchantRef(RefundLine line) {
    18	        return Refs.sanitize(line.orderNo());
    19	    }
    20	
    21	    public static String format(List<RefundLine> lines) {
    22	        StringBuilder sb = new StringBuilder();
    23	        for (RefundLine l : lines) {
    24	            sb.append(l.tid()).append('\t').append(l.amount()).append('\t').append(merchantRef(l)).append('\n');
    25	        }
    26	        return sb.toString();
    27	    }
    28	
    29	    public static Path write(Path dir, String batchId, List<RefundLine> lines) {
    30	        try {
    31	            Files.createDirectories(dir);
    32	            Path file = dir.resolve(batchId + ".tsv");
    33	            Files.writeString(file, format(lines), StandardCharsets.UTF_8);
    34	            return file;
    35	        } catch (IOException e) {
    36	            throw new IllegalStateException("cannot write refund batch " + batchId, e);
    37	        }
    38	    }
    39	}
